python3 -c "
import pandas as pd
import json

df_tasks = pd.read_csv('/app/dataset/tasks.csv')
task_pay = dict(zip(df_tasks['task_id'], df_tasks['pay_per_completion']))

df_time = pd.read_csv('/app/dataset/timesheet.csv')

def parse_tasks(val):
    if pd.isna(val) or val == '':
        return []
    val = val.strip()
    if not val.endswith(']'):
        val = val + ']'
    try:
        return json.loads(val)
    except:
        return []

mismatches = 0
for idx, row in df_time.iterrows():
    tasks = parse_tasks(row['performed_tasks'])
    # sum pay
    calc_bonus = sum(task_pay.get(t, 0) for t in tasks)
    actual_bonus = row['bonus']
    if calc_bonus != actual_bonus:
        print(f'Row {idx}: tasks={tasks}, raw_tasks={row[\"performed_tasks\"]}, calc_bonus={calc_bonus}, actual_bonus={actual_bonus}')
        mismatches += 1
        if mismatches > 20:
            break
print('Total mismatches checked so far:', mismatches)
"
